using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class AnalyticsPage:UserControl{public AnalyticsPage(){BackColor=Theme.Background;var cards=new FlowLayoutPanel{Dock=DockStyle.Top,Height=145,WrapContents=true};cards.Controls.Add(Card(L.Fa?"نرخ استخدام":"Hire rate","SELECT CASE WHEN COUNT(*)=0 THEN 0 ELSE 100*SUM(CASE WHEN Stage='Hired' THEN 1 ELSE 0 END)/COUNT(*) END FROM Applications","%"));cards.Controls.Add(Card(L.Fa?"مصاحبه‌های برنامه‌ریزی‌شده":"Scheduled interviews","SELECT COUNT(*) FROM Interviews WHERE Status='Scheduled'",""));cards.Controls.Add(Card(L.Fa?"پیشنهادهای باز":"Open offers","SELECT COUNT(*) FROM Offers WHERE Status='Draft' OR Status='Sent'",""));cards.Controls.Add(Card(L.Fa?"میانگین امتیاز":"Average score","SELECT ISNULL(AVG(CAST(Score AS FLOAT)),0) FROM Applications WHERE Score IS NOT NULL",""));Controls.Add(cards);var tabs=new TabControl{Dock=DockStyle.Fill};tabs.TabPages.Add(Tab(L.Fa?"قیف استخدام":"Recruitment funnel","SELECT Stage AS [Stage],COUNT(*) AS [Count] FROM Applications GROUP BY Stage ORDER BY COUNT(*) DESC"));tabs.TabPages.Add(Tab(L.Fa?"عملکرد فرصت‌ها":"Job performance","SELECT TOP 20 j.Title AS [Job],COUNT(a.Id) AS [Applications],AVG(CAST(a.Score AS FLOAT)) AS [AvgScore] FROM Jobs j LEFT JOIN Applications a ON a.JobId=j.Id GROUP BY j.Title ORDER BY COUNT(a.Id) DESC"));tabs.TabPages.Add(Tab(L.Fa?"منابع استعداد":"Talent insights","SELECT City AS [City],COUNT(*) AS [Candidates],AVG(CAST(ExperienceYears AS FLOAT)) AS [AvgExperience] FROM Candidates GROUP BY City ORDER BY COUNT(*) DESC"));Controls.Add(tabs);tabs.BringToFront();}Panel Card(string t,string sql,string suffix){var p=Ui.Card();p.Width=245;p.Height=120;var v=Database.Scalar(sql);var a=Ui.Label(t,10,true);a.Location=new Point(18,15);var n=Ui.Label(Convert.ToString(v)+suffix,24,true);n.ForeColor=Theme.Primary;n.Location=new Point(18,52);p.Controls.Add(a);p.Controls.Add(n);return p;}TabPage Tab(string title,string sql){var t=new TabPage(title){BackColor=Theme.Surface};var g=Ui.Grid();g.DataSource=Database.Query(sql);t.Controls.Add(g);return t;}}}
